import { beforeBlockString } from "../beforeBlockString/index.js";
import { hasBlock } from "../hasBlock/index.js";
import { statementString } from "../statementString/index.js";
/**
 * Returns a statement's block, `{` to `}`, or an empty string where it has none.
 * @param statement - The container.
 * @param result - The Stylelint result.
 * @returns The block.
 */
export function blockString(statement, result) {
    if (!hasBlock(statement))
        return ``;
    return statementString(statement, result).slice(beforeBlockString(statement, result, { noRawBefore: true }).length);
}
